from typing import Dict, Any, Iterable

def hide_passwords(users: Iterable[Dict[str, Any]]) -> Dict[Any, Dict[str, Any]]:
    """Return a dictionary keyed by user id, with the password removed from each record.

    The comprehension builds the result in one expression, so no mutation of
    the input records or the accumulator takes place.
    """
    return {
        user["id"]: {
            k: v for k, v in user.items() if k != "password"
        }
        for user in users
    }
```

